use App\Results\{TrackingStore,TelegramReportSender};$s=TrackingStore::settings();if(empty($s['enabled'])||empty($s['daily_report']))exit(0);$tz=new DateTimeZone('America/Sao_Paulo');$date=(new DateTimeImmutable('yesterday',$tz))->format('Y-m-d');if(!TrackingStore::markReport($date))exit(0);$r=TrackingStore::report($date);$settled=(int)($r['greens']??0)+(int)($r['reds']??0)+(int)($r['voids']??0)+(int)($r['half_greens']??0)+(int)($r['half_reds']??0);$decisions=(int)($r['greens']??0)+(int)($r['reds']??0)+(int)($r['half_greens']??0)+(int)($r['half_reds']??0);$hit=$decisions?((int)$r['greens']+(0.5*(int)$r['half_greens']))/$decisions*100:0;$staked=$settled*10;$roi=$staked?((float)$r['profit']/$staked*100):0;$text="📊 RELATÓRIO DIÁRIO\n".date('d/m/Y',strtotime($date))."\n\nApostas: ".(int)$r['total']."\n🟢 Greens: ".(int)$r['greens']."\n🔴 Reds: ".(int)$r['reds']."\n⚪ Void: ".(int)$r['voids']."\n⏳ Pendentes: ".(int)$r['pending']."\n\nTaxa de acerto: ".number_format($hit,2,',','.')."%\nStake padrão: 10 unidades\nResultado: ".number_format((float)$r['profit'],2,',','.')." unidades\nROI: ".number_format($roi,2,',','.')."%\nOdd média: ".number_format((float)$r['avg_odds'],2,'.','');if(!empty($s['test_mode'])){error_log('TMR_DAILY_REPORT_TEST '.json_encode(['date'=>$date,'text'=>$text],JSON_UNESCAPED_UNICODE));exit(0);}try{TelegramReportSender::send((string)$s['report_chat'],$text);error_log('TMR_DAILY_REPORT_SENT '.json_encode(['date'=>$date],JSON_UNESCAPED_UNICODE));}catch(Throwable $e){error_log('TMR_DAILY_REPORT_SEND_FAILED '.get_class($e));}
